import { fetchCartChunks } from "./cart-html";

export async function refreshMiniCart(): Promise<void> {
  const minicart = document.querySelector("uwp-minicart");
  const attrUpsells = minicart?.getAttribute("minicart-upsells") || "";

  const { body, footer, upsells } = await fetchCartChunks();

  const bodyTarget = document.querySelector(".minicart__body");
  if (bodyTarget) bodyTarget.innerHTML = body;

  const footerTarget = document.querySelector(".minicart__footer");
  if (footerTarget) footerTarget.innerHTML = footer;

  const upsellsTarget = document.querySelector(
    ".minicart__upsells",
  ) as HTMLElement | null;
  const upsellsHtml = (attrUpsells || upsells).trim();
  if (upsellsTarget) {
    if (upsellsHtml) {
      upsellsTarget.innerHTML = upsellsHtml;
      upsellsTarget.style.display = "";
    } else {
      upsellsTarget.innerHTML = "";
      upsellsTarget.style.display = "none";
    }
  }
}
